drop trigger if exists dispatches_touch on public.dispatches;
create trigger dispatches_touch before update on public.dispatches for each row execute function private.touch_updated_at();

-- kick: after insert, or after an update that sets status back to 'queued' (requeue), post {dispatch_id} to the
-- dispatch Edge Function through pg_net (the request is sent after this transaction commits). Secrets from Vault.
create or replace function private.dispatch_kick()
returns trigger language plpgsql security definer set search_path = '' as $$
declare v_url text; v_key text; v_dry boolean;
begin
  select decrypted_secret into v_url from vault.decrypted_secrets where name = 'public_functions_url';
  select decrypted_secret into v_key from vault.decrypted_secrets where name = 'supabase_secret_key';
  if v_url is null or v_key is null then
    update public.dispatches set status = 'failed', error = jsonb_build_object('reason', 'vault secrets missing') where id = new.id;
    return new;
  end if;
  perform extensions.net.http_post(
    url := v_url || '/dispatch',
    body := jsonb_build_object('dispatch_id', new.id),
    headers := jsonb_build_object('Content-Type', 'application/json', 'apikey', v_key),
    timeout_milliseconds := 20000);
  return new;
end $$;
drop trigger if exists dispatches_kick on public.dispatches;
create trigger dispatches_kick after insert or update of status on public.dispatches
  for each row when (new.status = 'queued') execute function private.dispatch_kick();

