-- ── emit_event: the only write path (N3), idempotent on idempotency_key ────────────────────────────
create or replace function private.emit_event(
  p_type text, p_payload jsonb, p_idempotency_key text, p_source text, p_site_id uuid,
  p_run_id uuid default null, p_machine_id uuid default null, p_operator_id uuid default null,
  p_task_id uuid default null, p_alert_id uuid default null, p_sim_ts timestamptz default null,
  p_tier public.alert_tier default null, p_correlation_id uuid default null, p_causation_id uuid default null
) returns public.events language plpgsql security definer set search_path = '' as $$
declare et public.event_types%rowtype; ev public.events%rowtype;
begin
  select * into et from public.event_types where type = p_type;
  if not found then raise exception 'unknown event type %', p_type using errcode = 'P0001'; end if;
  insert into public.events (run_id, type, tier, sim_ts, site_id, machine_id, operator_id, task_id, alert_id,
                             audiences, source, payload, correlation_id, causation_id, idempotency_key)
  values (p_run_id, p_type, coalesce(p_tier, et.default_tier), p_sim_ts, p_site_id, p_machine_id, p_operator_id,
          p_task_id, p_alert_id, et.audiences, p_source, p_payload, p_correlation_id, p_causation_id, p_idempotency_key)
  on conflict (idempotency_key) do nothing
  returning * into ev;
  if ev.id is null then
    select * into ev from public.events where idempotency_key = p_idempotency_key;   -- the duplicate returns the original
  end if;
  return ev;
end $$;

-- after insert: fan-out to one private topic per audience, then queue ledger / Loop work and nothing else (N2, N3)
create or replace function private.events_after_insert()
returns trigger language plpgsql security definer set search_path = '' as $$
declare et public.event_types%rowtype; a public.audience; topic text; body jsonb;
begin
  body := to_jsonb(new);
  foreach a in array new.audiences loop
    topic := case a
      when 'operator' then 'op:' || new.operator_id::text
      when 'site' then 'site:' || new.site_id::text
      when 'supervisor' then 'sup:' || new.site_id::text
      when 'trainer' then 'train:' || new.site_id::text end;
    if topic is not null and topic not like '%:' then   -- an operator audience with no operator id has no topic
      perform realtime.send(body, 'event', topic, true);
    end if;
  end loop;
  select * into et from public.event_types where type = new.type;
  if et.ledger then
    insert into private.ledger_queue (idempotency_key, event_id, entry)
    values ('ledger:' || new.idempotency_key, new.id, jsonb_build_object('event_id', new.id, 'type', new.type))
    on conflict (idempotency_key) do nothing;
  end if;
  if et.lesson_code is not null or et.replay then
    insert into private.loop_queue (event_id) values (new.id) on conflict (event_id) do nothing;
  end if;
  return null;
end $$;
drop trigger if exists events_after_insert on public.events;
create trigger events_after_insert after insert on public.events for each row execute function private.events_after_insert();

-- append-only for API roles: only private.purge_run (owner) deletes rehearsal rows
create or replace function private.events_block_mutation()
returns trigger language plpgsql set search_path = '' as $$
begin
  raise exception 'events are append-only' using errcode = '42501';
end $$;
drop trigger if exists events_no_update on public.events;
create trigger events_no_update before update on public.events for each row execute function private.events_block_mutation();

-- ── RLS ────────────────────────────────────────────────────────────────────────────────────────────
alter table public.events enable row level security;
alter table public.alerts enable row level security;
alter table public.dispatches enable row level security;
alter table public.lessons enable row level security;
alter table public.lesson_assignments enable row level security;
alter table public.replay_templates enable row level security;
alter table public.replay_scenarios enable row level security;
alter table public.replay_attempts enable row level security;

-- events: one rule per audience, mirroring the Realtime topics exactly (G2-19)
drop policy if exists events_read on public.events;
create policy events_read on public.events for select to authenticated using (
  ('operator' = any (audiences) and operator_id = (select private.my_operator_id()))
  or ('site' = any (audiences) and site_id = (select private.my_site_id()))
  or ((select private.is_fm()) and site_id = (select private.my_site_id()))
  or ((select private.app_role()) = 'trainer' and 'trainer' = any (audiences))
);
drop policy if exists alerts_read on public.alerts;
create policy alerts_read on public.alerts for select to authenticated
  using (operator_id = (select private.my_operator_id()) or (select private.is_fm()));
drop policy if exists dispatches_read on public.dispatches;
create policy dispatches_read on public.dispatches for select to authenticated using ((select private.is_fm()));
drop policy if exists lessons_read_all on public.lessons;
create policy lessons_read_all on public.lessons for select to authenticated using (true);
drop policy if exists replay_templates_read on public.replay_templates;
create policy replay_templates_read on public.replay_templates for select to authenticated using ((select private.app_role()) = 'trainer');
do $$
declare t text;
begin
  foreach t in array array['lesson_assignments', 'replay_scenarios', 'replay_attempts'] loop
    execute format('drop policy if exists %I on public.%I', t || '_read', t);
    execute format('create policy %I on public.%I for select to authenticated using (operator_id = (select private.my_operator_id()) or (select private.app_role()) = ''trainer'')', t || '_read', t);
  end loop;
end $$;

-- grants: select only; replay_scenarios without the answer key; events/alerts/dispatches never writable by clients
grant select on public.events, public.alerts, public.dispatches, public.lessons, public.lesson_assignments,
  public.replay_templates, public.replay_attempts to authenticated;
grant select (id, source_event_id, operator_id, template_version, scenario_json, created_at) on public.replay_scenarios to authenticated;
revoke update, delete on public.events from anon, authenticated, service_role;

-- realtime.messages: a role may receive on exactly the topics its events policy covers (api-contracts §7)
drop policy if exists spotter_receive on realtime.messages;
create policy spotter_receive on realtime.messages for select to authenticated using (
  realtime.messages.extension = 'broadcast' and (
    (select realtime.topic()) = 'op:' || (select private.my_operator_id())::text
    or (select realtime.topic()) = 'site:' || (select private.my_site_id())::text
    or ((select private.is_fm()) and (select realtime.topic()) = 'sup:' || (select private.my_site_id())::text)
    or ((select private.app_role()) = 'trainer' and (select realtime.topic()) = 'train:' || (select private.my_site_id())::text)
  )
);

-- ── my_snapshot (api-contracts §4 MySnapshotOut) ───────────────────────────────────────────────────
create or replace function public.my_snapshot()
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  me public.profiles%rowtype; run public.scenario_runs%rowtype; v_machine_id uuid; v_tel text; v_sim_now timestamptz;
  j_tasks jsonb; j_alerts jsonb; j_machine jsonb; j_state jsonb; j_weather jsonb; j_assign jsonb; j_events jsonb; j_site jsonb;
begin
  select * into me from public.profiles where user_id = (select auth.uid());
  if not found then raise exception 'forbidden' using errcode = 'P0001'; end if;
  select * into run from public.scenario_runs where is_current limit 1;
  if run.id is not null then
    v_sim_now := case when run.status = 'playing' then run.sim_anchor + (now() - run.wall_anchor) * run.speed else run.sim_anchor end;
  end if;
  select decrypted_secret into v_tel from vault.decrypted_secrets where name = 'site_emergency_tel';
  select jsonb_build_object('id', s.id, 'name', s.name, 'emergency_tel', v_tel) into j_site from public.sites s where s.id = me.site_id;
  if me.operator_id is not null then
    select machine_id into v_machine_id from public.operator_pairings
      where operator_id = me.operator_id and unpaired_at is null and (run_id = run.id or (run.id is null and run_id is null))
      order by paired_at desc limit 1;
  end if;

  select coalesce(jsonb_agg(jsonb_build_object('id', t.id, 'task_type', t.task_type, 'status', t.status,
      'planned_start', t.planned_start, 'progress_pct', t.progress_pct, 'eta_p50_min', t.eta_p50_min,
      'eta_p90_min', t.eta_p90_min, 'eta_factors', t.eta_factors) order by t.planned_start), '[]')
    into j_tasks
    from public.tasks t
    where (run.id is null or t.run_id = run.id)
      and (t.operator_id = me.operator_id or (me.role in ('fleet_manager', 'trainer') and t.site_id = me.site_id));

  select coalesce(jsonb_agg(jsonb_build_object('alert_id', a.id, 'kind', a.kind, 'tier', a.tier, 'needs_ack', a.needs_ack,
      'escalate_at', a.escalate_at, 'occurrences', a.occurrences, 'protocol_card_id', a.protocol_card_id,
      'upgraded_from', (a.tier_history -> -1 ->> 'from'), 'status', a.status, 'first_seen', a.first_seen)
      order by a.first_seen desc), '[]')
    into j_alerts
    from public.alerts a
    where a.status in ('open', 'acknowledged', 'escalating')
      and (a.operator_id = me.operator_id or (me.role = 'fleet_manager' and a.site_id = me.site_id));

  if v_machine_id is not null then
    select jsonb_build_object('id', m.id, 'code', m.code, 'model_name', mm.name,
        'moving', coalesce(ms.moving, false), 'speed_kmh', coalesce(ms.speed_kmh, 0), 'health', coalesce(ms.health, 'ok'),
        'location', jsonb_build_object('lat', coalesce(extensions.ST_Y(ms.location::extensions.geometry), extensions.ST_Y(s.location::extensions.geometry)),
                                       'lon', coalesce(extensions.ST_X(ms.location::extensions.geometry), extensions.ST_X(s.location::extensions.geometry))),
        'seatbelt_fastened', ms.seatbelt_fastened, 'parking_brake', ms.parking_brake)
      into j_machine
      from public.machines m
      left join public.machine_models mm on mm.id = m.model_id
      left join public.machine_state ms on ms.machine_id = m.id and ms.run_id = run.id
      join public.sites s on s.id = me.site_id
      where m.id = v_machine_id;
  end if;

  if me.operator_id is not null then
    select jsonb_build_object('on_foot', os.on_foot, 'ppe', os.ppe,
        'location', case when os.location is null then null else jsonb_build_object('lat', extensions.ST_Y(os.location::extensions.geometry), 'lon', extensions.ST_X(os.location::extensions.geometry)) end,
        'ts', os.ts, 'motion_locked', os.motion_locked, 'call_allowed', os.call_allowed, 'nearest', os.nearest)
      into j_state
      from public.operator_state os where os.operator_id = me.operator_id and os.run_id = run.id;
  end if;

  select jsonb_build_object('ts', w.ts, 'temperature_c', w.temperature_c, 'wbgt_c', w.wbgt_c, 'wind_chill_c', w.wind_chill_c,
      'wind_kmh', w.wind_kmh, 'forecast_peak_c', w.forecast_peak_c, 'forecast_peak_at', w.forecast_peak_at,
      'source_label', case when w.source = 'open_meteo_archive' then 'Open-Meteo archive, CC BY 4.0 (scenario forecast)' else w.source end)
    into j_weather
    from public.weather_snapshots w
    where w.site_id = me.site_id and (run.id is null or w.run_id = run.id or w.run_id is null)
    order by (w.run_id = run.id) desc nulls last, w.ts desc limit 1;

  select coalesce(jsonb_agg(jsonb_build_object('id', la.id, 'lesson_code', l.code, 'because_event_id', la.because_event_id,
      'replay_id', rs.id) order by la.assigned_at desc), '[]')
    into j_assign
    from public.lesson_assignments la
    join public.lessons l on l.id = la.lesson_id
    left join public.replay_scenarios rs on rs.source_event_id = la.because_event_id and rs.operator_id = la.operator_id
    where la.operator_id = me.operator_id and la.completed_at is null;

  select coalesce(jsonb_agg(to_jsonb(e) order by e.seq desc), '[]') into j_events
    from (select * from public.events e
          where ('operator' = any (e.audiences) and e.operator_id = me.operator_id)
             or ('site' = any (e.audiences) and e.site_id = me.site_id)
             or (me.role = 'fleet_manager' and e.site_id = me.site_id)
             or (me.role = 'trainer' and 'trainer' = any (e.audiences))
          order by e.seq desc limit 50) e;

  return jsonb_build_object(
    'contracts_version', '1.0.0',
    'profile', jsonb_build_object('user_id', me.user_id, 'role', me.role, 'operator_id', me.operator_id, 'site_id', me.site_id, 'language', me.language),
    'server_now', now(),
    'run', case when run.id is null then null else jsonb_build_object('id', run.id, 'status', run.status, 'speed', run.speed, 'sim_now', v_sim_now) end,
    'site', j_site,
    'paired_machine_id', v_machine_id,
    'tasks', j_tasks,
    'active_alerts', j_alerts,
    'machine', j_machine,
    'operator_state', j_state,
    'weather', j_weather,
    'assignments', j_assign,
    'recent_events', j_events);
end $$;
revoke execute on function public.my_snapshot() from public, anon;
grant execute on function public.my_snapshot() to authenticated;
